END $$;

DO $$
BEGIN
    IF to_regclass('pos_day_closes') IS NOT NULL THEN
        IF NOT EXISTS (
            SELECT 1 FROM information_schema.columns
            WHERE table_name = 'pos_day_closes' AND column_name = 'closed_by_display_name'
        ) THEN
            ALTER TABLE pos_day_closes ADD COLUMN closed_by_display_name VARCHAR(150);
            RAISE NOTICE 'Added closed_by_display_name to pos_day_closes';
        END IF;
    END IF;
END $$;
